  spartacus: { n: 'Повстання Спартака', p: 'Кампанія, Італія', d: 'Фракійський гладіатор веде 70 000 утікачів-рабів уздовж усієї Італії, перемагаючи легіон за легіоном — аж до розп’ять уздовж Аппієвої дороги.' },
  caesar: { n: 'Гай Юлій Цезар', p: 'Рим', d: 'Завойовник Галлії, перетнув Рубікон, довічний диктатор — убитий у березневі іди сенаторами, які боялися царя.' },
  gaul: { n: 'Цезар підкорює Галлію', p: 'Галлія', d: '«Вся Галлія ділиться на три частини» — вісім років різанини та геніального нарису, і Галлія стає римською.' },
  cleopatra: { n: 'Клеопатра VII', p: 'Александрія, Єгипет', d: 'Остання цариця Єгипту — володіла дев’ятьма мовами — кохає Цезаря й Антонія в приреченій спробі врятувати своє царство від Риму.' },
  actium: { n: 'Битва при Актії', p: 'Актій, Греція', d: 'Октавіан перемагає Антонія та Клеопатру; останні суперники Республіки падають — і починається доба імператорів.' },
  augustus: { n: 'Август — перший імператор', p: 'Рим', d: 'Октавіан стає «Августом» і перетворює Рим на імперію; мир, мармур і Pax Romana йдуть услід.' },
  roman_empire: { n: 'Римська імперія', p: 'Рим', d: 'У розквіті за Траяна Рим править від Британії до Перської затоки — 70 мільйонів людей, один закон, дороги, що існують досі.' },
  jesus: { n: 'Ісус із Назарета', p: 'Юдея', d: 'Галилейський проповідник, розп’ятий Римом, стає центром найбільшої релігії світу; його послідовники поділять історію на «до» і «після».' },
  fire_rome: { n: 'Велика пожежа Риму', p: 'Рим', d: 'Шість днів вогню випалюють місто; чутки звинувачують Нерона, а Нерон — християн.' },
