  harald_fairhair: { n: 'Гаральд Прекрасноволосий об’єднує Норвегію', p: 'Гафрсфйорд, Норвегія', d: 'Перемога в Гафрсфйорді (традиційна дата 872) робить Гаральда першим королем усієї Норвегії — а саги кажуть, що переможені рушили на захід, засновувати Ісландію.' },
  jelling: { n: 'Камені Єлінга — Данія стає християнською', p: 'Єлінг, Данія', d: 'Король Гаральд Синій Зуб ставить «хрестильну грамоту Данії»: «Гаральд, що здобув усю Данію й Норвегію та зробив данів християнами».' },
  lanse_meadows: { n: 'Вікінги досягають Америки', p: 'Л’Анс-о-Медоуз, Канада', d: 'Вікінги будують базу в Л’Анс-о-Медоуз на Ньюфаундленді — деревину датовано науково рівно 1021 роком; європейське відкриття Америки — на 471 рік раніше за Колумба.' },
