  kievan_rus: { n: 'Київська Русь', p: 'Київ', d: 'Князь Олег здобуває Київ і робить його столицею держави від Балтійського до Чорного моря — середньовічна держава з центром у нинішньому Києві, від якої українці, білоруси й росіяни виводять свої початки.' },
  kyiv_founding: { n: 'Легендарне заснування Києва', p: 'Київ', d: '«Повість минулих літ» називає засновниками братів Кия, Щека й Хорива та сестру Либідь; 482 рік — умовна дата, ухвалена до 1 500-річчя міста в 1982 році.' },
