  yaroslav: { n: 'Ярослав Мудрий', p: 'Київ', d: 'За нього Київська Русь сягає вершини: письмовий законник «Руська Правда», перші бібліотеки й школи східних слов’ян, династичні шлюби, що посадили його дітей на трони від Франції до Угорщини.' },
  sophia_kyiv: { n: 'Освячено Софію Київську', p: 'Київ', d: 'Тринадцятибанний собор Ярослава із золотими мозаїками стає духовним і політичним серцем Русі — а 988 років потому — символом України.' },
  primary_chronicle: { n: 'Складено «Повість минулих літ»', p: 'Києво-Печерська лавра', d: 'Головне джерело з ранньої історії східних слов’ян постає в Києві — починаючись із власної розповіді русі про те, ким вони є.' },
