  galicia_volhynia: { n: 'Галицько-Волинське королівство', p: 'Галич, Україна', d: 'Західне продовження Русі: князь Роман об’єднує Галич і Волинь; 1253 року його син Данило коронується від папського легата. Остання незалежна руська держава протистоїть Орді, доки Польща й Литва не поглинають її (1340-ті).' },
  danylo: { n: 'Король Данило Галицький', p: 'Галич і Холм', d: 'Засновник Львова (бл. 1256) і будівник королівства укріплених міст; коронований «королем Русі» 1253 року, він так і не схилився перед Золотою Ордою.' },
