  livonian_crusade: { n: 'Північні хрестові походи на Балтиці', p: 'Лівонія (Латвія/Естонія)', d: 'Мечоносні ордени та князі-єпископи вогнем і мечем підкорюють Лівонію й Естонію; падають також стара Пруссія та Курляндія — лише литовці зупиняють хрестовий похід і лишаються язичниками ще століття.' },
  riga_founded: { n: 'Заснування Риги', p: 'Рига, Латвія', d: 'Єпископ Альберт засновує Ригу в гирлі Даугави; 1282 року вона вступає до Ганзейського союзу й століттями домінує в балтійській торгівлі.' },
  lyndanisse: { n: 'Битва при Лінданісе та Данеброґ', p: 'Таллінн, Естонія', d: 'Вальдемар II Данський бере Ревель — а за легендою, червоно-білий прапор падає з неба; данська Естонія триває до 1346-го, а прапор Данії стає найстарішим діючим у світі.' },
