  curie: { n: 'Марія Кюрі', p: 'Париж', d: 'Дві Нобелівські премії у двох науках; вона вводить термін «радіоактивність» і носить радій у кишенях до самої смерті.' },
  hrushevsky: { n: 'Михайло Грушевський', p: 'Київ', d: 'Його десятитомна «Історія України-Русі» повернула Київську Русь в українську історію — наукову відповідь імперській школі, що анексувала її до російського минулого; 1917 року він очолив перший український парламент — Центральну Раду — і помер у радянському засланні.' },
  opium_war: { n: 'Перша опіумна війна', p: 'Кантон, Китай', d: 'Британія воює за право продавати Китаю опіум — і здобуває Гонконг та договірні порти під дулами канонерок.' },
  taiping: { n: 'Повстання тайпінів', p: 'Нанкін, Китай', d: 'Сільський учитель, що оголосив себе молодшим братом Христа, підпалює найкривавішу громадянську війну в історії — 20 мільйонів загиблих.' },
  suez: { n: 'Відкриття Суецького каналу', p: 'Суец, Єгипет', d: 'Середземне море зустрічається з Червоним: морський шлях до Індії коротшає на 8 900 км.' },
