  executed_renaissance: { n: 'Розстріляне відродження', p: 'Харків і Київ', d: 'Сяйвове покоління українських 1920-х — проза Хвильового, театр «Березіль» Курбаса, неокласицизм Зерова — знищене масовими арештами; у листопаді 1937-го сотні письменників, науковців і митців республіки розстріляні в урочищі Сандармох.' },
  ww2: { n: 'Друга світова війна', p: 'Весь світ', d: 'Найсмертоносніший конфлікт в історії: 70–85 мільйонів загиблих, Голокост і світовий лад, відбудований з попелу.' },
  soviet_baltic_occupation: { n: 'Радянська окупація Балтії', p: 'Естонія · Латвія · Литва', d: 'Таємний протокол, ультиматум, анексія (1940); десятки тисяч вивезені скотськими вагонами до Сибіру в 1941 та 1949 роках; «Лісові брати» воюють із лісів до 1950-х. Окупація триває до 1991 року.' },
  winter_war: { n: 'Зимова війна', p: 'Карельський перешийок, Фінляндія', d: 'Сталін кидає 450 000 військових у Фінляндію посеред арктичної зими — і фіни, на лижах і з «коктейлями Молотова», тримаються 105 днів; землями поступилися, але не підкорилися.' },
  holocaust: { n: 'Голокост', p: 'Окупована Європа', d: 'Нацистська Німеччина ставить геноцид на промислові рейки: шість мільйонів євреїв, а також роми, слов’яни, політичні в’язні та інші — убиті.' },
