  dday: { n: 'День Д', p: 'Нормандія, Франція', d: 'Найбільша десантна операція в історії — 156 000 союзних військових висаджуються у Франції й розпочинають звільнення Західної Європи.' },
  babi_yar: { n: 'Розстріли в Бабиному Яру', p: 'Київ', d: '29–30 вересня 1941 року айнзацгрупа C розстрілює 33 771 єврея Києва в яру Бабин Яр — один із наймасовіших одиночних розстрілів Голокосту; за часів окупації там убито ще десятки тисяч людей.' },
  upa: { n: 'Українська повстанська армія (УПА)', p: 'Західна Україна', d: 'Партизанська армія, що боролася за незалежну українську державу проти радянських і німецьких сил — і причетна до етнічних чисток польського населення на Волині (1943–44), які й досі лихою тінню лежать на польсько-українській пам’яті. Радянське полювання на УПА тривало до 1950-х.' },
  hiroshima: { n: 'Атомне бомбардування Хіросіми', p: 'Хіросіма, Японія', d: 'Одна бомба знищує місто за секунди; понад 70 000 людей гине одразу — і починається ядерна доба.' },
  churchill: { n: 'Вінстон Черчилль', p: 'Лондон', d: '«Ми будемо битися на пляжах» — голос, що тримав непокірність Британії крізь 1940-й.' },
  fdr: { n: 'Франклін Д. Рузвельт', p: 'Вашингтон', d: 'Чотири каденції, Новий курс і світова війна — він помирає за тижні до перемоги, переформатувавши сучасне президентство.' },
  stalin: { n: 'Йосип Сталін', p: 'Москва', d: 'Колективізація, чистки та ГУЛАГ убивають мільйони — а «людина зі сталі» водночас індустріалізує СРСР і виграє війну на Сході.' },
  un_founded: { n: 'Заснування ООН', p: 'Сан-Франциско', d: '51 держава підписує Статут ООН у Сан-Франциско — «врятувати прийдешні покоління від лиха війни».' },
  india_independence: { n: 'Незалежність Індії та Поділ', p: 'Нью-Делі', d: 'Британський Радж завершується; народжуються Індія і Пакистан — і до мільйона людей гине в хаосі Поділу, 15 мільйонів тікають.' },
