  gagarin: { n: 'Ґагарін обертається навколо Землі', p: 'Байконур', d: '«Поїхали!» — 108 хвилин, що назавжди роблять Юрія Ґагаріна першою людиною в космосі.' },
  everest: { n: 'Перше сходження на Еверест', p: 'Еверест', d: 'Гілларі й Тенцинг стоять на вершині світу 29 травня 1953 року — звістка доходить до Лондона в день коронації.' },
