  eng_harold_ii: { n: 'Гарольд II Ґодвінсон', p: 'Лондон', d: 'Останній англосаксонський король: розбив норвежців при Стемфорд-Бріджі, рушив на південь і впав при Гастінґсі три тижні потому.' },
  eng_edgar_aetheling: { n: 'Едгар Етелінґ', p: 'Лондон', d: 'Обраний вітою після Гастінґса, але так і не коронований — законний спадкоємець, що скорився Вільгельму й дожив до хрестових походів.' },
