  eng_henry_ii: { n: 'Генріх II Плантагенет', p: 'Лондон', d: 'Імперія від Шотландії до Піренеїв: Бекет, убитий у власному соборі, — і спільне право, побудоване його суддями.' },
  eng_richard_i: { n: 'Річард I Левине Серце', p: 'Лондон', d: 'Третій хрестовий похід, полон в Австрії, десять тижнів в Англії за десятиліття правління — і арбалетна стріла при Шалю.' },
  eng_john: { n: 'Іоанн Безземельний', p: 'Лондон', d: 'Втратив Нормандію, посварився з папою — і в Ранніміді запечатав Велику хартію вольностей (1215) під ножами баронів.' },
  eng_henry_iii: { n: 'Генріх III', p: 'Лондон', d: 'Найдовше середньовічне княження: перебудував Вестмінстер у ґотиці — поки баронські постанови народжували англійський парламент.' },
  eng_edward_i: { n: 'Едуард I Довгоногий', p: 'Лондон', d: '«Зразковий парламент», завоювання Вельсу — і «Молот шотландців», як читається на його гробниці.' },
