  eng_edward_iii: { n: 'Едуард III', p: 'Лондон', d: 'Лицарська вершина: Кресі та Пуатьє, орден Підв’язки — і Столітня війна, відкрита його французькою претензією.' },
  eng_richard_ii: { n: 'Річард II', p: 'Лондон', d: 'Коронований у десять, розтрощив Селянське повстання у чотирнадцять — а тоді схоплений кузеном Болінброком і заморений голодом у Понтефракті.' },
  eng_henry_iv: { n: 'Генріх IV Болінброк', p: 'Лондон', d: 'Узурпатор, що взяв корону замість спадку — чотирнадцять років переслідуваний повстаннями.' },
  eng_henry_v: { n: 'Генріх V', p: 'Лондон', d: 'Азенкур (1415) і Труаський договір: спадкоємець французької корони — пмер у тридцять п’ять, за тижні до французького короля.' },
  eng_henry_vi: { n: 'Генріх VI', p: 'Лондон', d: 'Набожний король-немовля, чиї два княження розвалилися у Війну троянд — убитий у Тавері вночі повернення Йорка (1471).' },
  eng_edward_iv: { n: 'Едуард IV', p: 'Лондон', d: 'Йоркіст-виживальник: переміг при Таутоні й Тьюксбері, прогуляв усе на коханок — пмер огрядним у сорок (1483).' },
  eng_edward_v: { n: 'Едуард V', p: 'Лондон', d: 'Хлопчик-король у Тавері: оголений дядьком незаконним і більше ніхто його не бачив — один із «принців із Тауера».' },
  eng_richard_iii: { n: 'Річард III', p: 'Лондон', d: 'Горбатий лиходій тюдорівської драми — чи здібний останній Плантагенет: убитий при Босворті (1485), знайдений під парковкою в Лестері 2012 року.' },
  eng_henry_vii: { n: 'Генріх VII Тюдор', p: 'Лондон', d: 'Король-бухгалтер: виграв Босворт, одружився з ворожою трояндою — і наповнив скарбницю банківською строгостю.' },
  eng_henry_viii: { n: 'Генріх VIII', p: 'Лондон', d: 'Шість дружин, дві обезголовлені: розірвав із Римом заради Анни Болейн і зробив себе головою англійської церкви.' },
  eng_edward_vi: { n: 'Едуард VI', p: 'Лондон', d: 'Хлопчик-реформатор: Англія стала кальвіністською його іменем — пмер у п’ятнадцять, не встигнувши коронувати леді Джейн своїм «заповітом».' },
  eng_jane_grey: { n: 'Леді Джейн Ґрей — дев’ятиденна королева', p: 'Лондон', d: 'Проголошена, скинута Марією за дев’ять днів, страчена у сімнадцять (1554) — пішак протестантизму на троні.' },
