  de_henry_ii: { n: 'Генріх II Святий', p: 'Бамберґ, Німеччина', d: 'Останній Оттон: засновує Бамберґське єпископство, воює зі святою списом у руці — канонізований 1146 року, єдиний німецький король, якого зробили святим.' },
  de_conrad_ii: { n: 'Конрад II', p: 'Шпаєр, Німеччина', d: '«Малий ґраф», обраний у розрахунку на посередність: замість цього оновив імперію, забрав Бурґундію і почав Шпаєрський собор як імператорську усипальницю.' },
  de_henry_iii: { n: 'Генріх III Чорний', p: 'Шпаєр, Німеччина', d: 'Імперська влада на зеніті: три суперечні папи скинуті в Сутрі (1046), реформоване папство поставлене під німецьку опіку — автократія, яку син уже не втримає.' },
  de_henry_iv: { n: 'Генріх IV', p: 'Гослар, Німеччина', d: 'Пішов у Каноссу (1077) — босоніж по снігу до папи Ґреґорія VII — і тридцять років війни з екскомунікаціями, антикоролями та громадянською війною; скінчив скинутим власним сином.' },
  de_henry_v: { n: 'Генріх V', p: 'Шпаєр, Німеччина', d: 'Зійшов на трон над зламаним тілом батька, потім воював у ту саму інвеститурну війну — і закрив її Вормським конкордатом (1122): церква й імперія, розлучені.' },
  de_lothar_ii: { n: 'Лотар II Суплінбурзький', p: 'Гослар, Німеччина', d: 'Обраний проти Штауфенів, водив папську армію до Рима, пмер на дорозі з Італії — лишивши Вельфів і Гогенштауфенів різати спадок ціле покоління.' },
  de_conrad_iii: { n: 'Конрад III', p: 'Нюрнберґ, Німеччина', d: 'Перший король із Гогенштауфенів: хрестовий похід скінчився катастрофою під Дорілеєм, вдома обложував вельфів — єдиний король свого віку, що так і не досяг імператорської коронації в Римі.' },
  de_frederick_barbarossa: { n: 'Фрідріх I Барбаросса', p: 'Нюрнберґ, Німеччина', d: 'Рудобородий і невтомний: канонізував Карла Великого, провів п’ять італійських походів до поразки при Леґнано (1176) й утопився у річці Салеф на Третьому хрестовому поході — його борода спить під Кіфгойзеном, німецьким майбутнім королем, що повернеться.' },
