  de_philip_swabia: { n: 'Філіпп Швабський', p: 'Бамберґ, Німеччина', d: 'Подвійні вибори розкололи Німеччину між двох королів — сторона Філіппа тримала багатство півдня, аж поки його не вбили на весільному бенкеті родич, якого він образив (1208).' },
  de_otto_iv: { n: 'Оттон IV', p: 'Брауншвейґ, Німеччина', d: 'Вельф, що зрештою переміг Філіппа, все одно був відлучений від церкви, а його армію розбила Франція під Бувіне (1214) — останній вельфівський імператор, обдертий власними курфюрстами.' },
  de_frederick_ii: { n: 'Фрідріх II — «диво світу»', p: 'Палермо, Італія', d: 'Король Сицилії, «диво світу»: шість мов, перша наукова книга про соколине полювання, двір арабських, грецьких і юдейських вчених — чотири рази відлучений, він узяв Єрусалим договором (1229) і пмер на полюванні: останній імператор середньовічного віку.' },
