  me_utuhegal: { n: 'Уту-Хегаль', p: 'Урук, Месопотамія', d: 'Цар Урука, який вигнав гутейських горян і відновив шумерське царювання — його переможна стела належить до останніх величних пам’яток старого Шумеру.' },
