  me_shamashshumukin: { n: 'Шамаш-шум-укін', p: 'Вавилон, Месопотамія', d: 'Брат Ашшурбаніпала, посаджений царем Вавилона під ассирійською зверхністю — його шестирічне повстання за свободу Вавилона скінчилося облогою, у якій, за одним переказом, він згорів у власному палаці.' },
  me_nabopolassar: { n: 'Набопаласар', p: 'Вавилон, Месопотамія', d: 'Халдей, який повернув Вавилону свободу і поховав Ассирію — разом із мідійськими союзниками він узяв штурмом Ніневію 612 до н. е., а завершальні західні походи лишив сину.' },
  me_nebuchadnezzar_ii: { n: 'Навуходоносор II', p: 'Вавилон, Месопотамія', d: 'Найвеличніший цар Вавилона: він розбив Єгипет під Кархемишем, 586 до н. е. узяв Єрусалим і спалив його, збудував Ворота Іштар та зиккурат, який пам’ятають як Вавилонську вежу.' },
