  me_nabonidus: { n: 'Набонід', p: 'Вавилон, Месопотамія', d: 'Останній цар Вавилона: відданий шанувальник місячного бога Сіна, який відвернув від себе жерців Мардука, провів десятиліття в оазі Тейма й 539 до н. е. без бою втратив місто на користь Кіра Персидського.' },
